cd /app/tmp/work && /app/submission/run.sh < eh.json | head -c 200; echo; python3 -c "
import json,sys
req=json.load(open('/app/tmp/work/eh.json'))
sys.path.insert(0,'/app/submission'); sys.path.insert(0,'/app/tmp/work')
import main as M, traceback
fbn={f['name']:f for f in req['schema']}
for i,a in enumerate(req['atoms']):
    try: M.validate_atom(a, req['window'], fbn)
    except M.ServiceError as e:
        tb=traceback.format_exc().splitlines()
        print('atom',i,e.code, tb[-4]); break
"
